    d.querySelector("input").onchange = (e) => {
      e.target.checked ? st.off.delete(f.key) : st.off.add(f.key); d.classList.toggle("off", !e.target.checked); save(); refilter();
    };
    d.classList.toggle("off", st.off.has(f.key));
