  const row = (k) => dial(k, defs[k], vals[k], (v) => {
    vals[k] = v;
    document.querySelectorAll(`#main-params .param[data-name="${k}"], #detect-params .param[data-name="${k}"]`).forEach((o) => { if (!o.contains(document.activeElement)) o.set(v); });
